INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('egeo-dolce', 'Egeo Dolce Desodorante Colônia', 'O Boticário', 'perfumes', 16490, 'Doce de verdade, no melhor sentido: marshmallow, algodão-doce, sorvete de framboesa e baunilha. É divertido, jovem e daqueles que fazem as pessoas perguntarem o que você está usando. Ótima escolha para quem gosta de perfume gourmand e quer algo leve para o dia a dia.', 'feminino', '[{"label":"Volume","value":"90 ml"},{"label":"Concentração","value":"Desodorante Colônia"}]', '{"familia":"Oriental gourmand","acordes":"Marshmallow, sorvete de framboesa, algodão-doce e baunilha","sensacao":"Divertida, doce e jovem.","ocasiao":"Dia a dia, faculdade e programas com amigos."}', 1, 3, 20, 1794096000000, 1794096000000);
