INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('malbec-colonia', 'Malbec Desodorante Colônia', 'O Boticário', 'perfumes', 21990, 'O clássico da perfumaria masculina brasileira. O contraste da pimenta com a bergamota abre a fragrância e as madeiras do patchouli e do musgo seguram o rastro. Elegante, confiável e sempre atual: se a dúvida é qual masculino escolher, este é o mais seguro.', 'masculino', '[{"label":"Volume","value":"100 ml"},{"label":"Concentração","value":"Desodorante Colônia"}]', '{"familia":"Amadeirado","acordes":"Pimenta, bergamota, patchouli e musgo","sensacao":"Marcante, confiante e elegante.","ocasiao":"Trabalho, dia a dia e noite."}', 1, 4, 21, 1794096000000, 1794096000000);
