INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('malbec-eau-de-parfum', 'Malbec Eau de Parfum', 'O Boticário', 'perfumes', 27990, 'O Malbec mais concentrado da linha, com até 12 horas de intensidade. Traz o couro de Grasse junto com o calor da baunilha e das especiarias, num resultado mais doce e mais sofisticado que o Malbec tradicional. É o Malbec de ocasião especial.', 'masculino', '[{"label":"Volume","value":"90 ml"},{"label":"Concentração","value":"Eau de Parfum"},{"label":"Fixação","value":"Até 12 horas"}]', '{"familia":"Amadeirado oriental","acordes":"Couro de Grasse, baunilha e especiarias","sensacao":"Sofisticada, quente e poderosa.","ocasiao":"Noite e ocasiões especiais."}', 1, 5, 22, 1794096000000, 1794096000000);
INSERT INTO fotos (id, produto_id, posicao, origem, src_grande, src_miniatura, largura, altura, bytes, criado_em) VALUES ('legado-malbec-eau-de-parfum', 'malbec-eau-de-parfum', 1, 'estatica', '/assets/img/products/w/malbec-eau-de-parfum.webp', '/assets/img/products/w/malbec-eau-de-parfum-600.webp', 1200, 1200, 0, 1794096000000);
INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('quasar-blue', 'Quasar Blue Desodorante Colônia', 'O Boticário', 'perfumes', 18990, 'O Quasar tradicional, agora chamado Blue. Frescor clássico de barbearia: cítrico na abertura, lavanda no coração e um fundo amadeirado seco e confortável. É aquele masculino que agrada todo mundo e serve para qualquer momento.', 'masculino', '[{"label":"Volume","value":"100 ml"},{"label":"Concentração","value":"Desodorante Colônia"}]', '{"familia":"Fougère fresco","acordes":"Cítrico, lavanda e madeiras secas","saida":"Limão e mandarina","coracao":"Lavanda e gerânio","fundo":"Cedro seco e musk","sensacao":"Limpa, clássica e confortável.","ocasiao":"Dia a dia e trabalho."}', 1, 6, 23, 1794096000000, 1794096000000);
INSERT INTO fotos (id, produto_id, posicao, origem, src_grande, src_miniatura, largura, altura, bytes, criado_em) VALUES ('legado-quasar-blue', 'quasar-blue', 1, 'estatica', '/assets/img/products/w/quasar-blue.webp', '/assets/img/products/w/quasar-blue-600.webp', 1200, 1200, 0, 1794096000000);
