INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('uomini', 'Uomini Desodorante Colônia', 'O Boticário', 'perfumes', 20990, 'Clássico do Boticário que segue firme: frescor aromático com a força das madeiras. Elegante sem ser pesado, tem cara de perfume de homem adulto e combina muito com o trabalho e com o dia a dia. Frasco em vidro reciclado, com acabamento fosco.', 'masculino', '[{"label":"Volume","value":"100 ml"},{"label":"Concentração","value":"Desodorante Colônia"}]', '{"familia":"Fougère aromático","acordes":"Frescor aromático e madeiras","sensacao":"Elegante, sóbria e madura.","ocasiao":"Trabalho, dia a dia e reuniões."}', 1, 9, 26, 1794096000000, 1794096000000);
