INSERT INTO produtos (id, nome, marca, categoria_id, preco_centavos, descricao, publico, ficha_json, fragrancia_json, ativo, destaque_pos, posicao, criado_em, atualizado_em) VALUES ('arbo', 'Arbo Desodorante Colônia', 'O Boticário', 'perfumes', 18990, 'Frescor de montanha: menta, notas verdes e sândalo. É leve, limpo e calmante — o tipo de fragrância que combina com dias quentes e com quem prefere algo discreto. Um dos masculinos mais fáceis de usar do Boticário.', 'masculino', '[{"label":"Volume","value":"100 ml"},{"label":"Concentração","value":"Desodorante Colônia"}]', '{"familia":"Fougère fresco","acordes":"Menta, notas verdes e sândalo","sensacao":"Fresca, leve e revigorante.","ocasiao":"Dia a dia, dias quentes e lazer."}', 1, 10, 27, 1794096000000, 1794096000000);
