INSERT INTO fotos (id, produto_id, posicao, origem, src_grande, src_miniatura, largura, altura, bytes, criado_em) VALUES ('legado-lattitude-stamina-hinode', 'lattitude-stamina-hinode', 1, 'estatica', '/assets/img/products/w/lattitude-stamina-hinode.webp', '/assets/img/products/w/lattitude-stamina-hinode-600.webp', 1200, 1200, 0, 1794096000000);
